; under.asm -- chapter 28: the colours under the bug
; generated by gen28.py
        INCLUDE "msx.inc"
        OUTPUT "under.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
names   EQU $C400               ; the tiles' names, a copy
shown   EQU $C800               ; the names on the screen
pats    EQU $CC00               ; the bugs' patterns; colours $400 on
copies  EQU $D400               ; the eight copies of the bug
bugs    EQU VARS                ; the bugs' records, 16 bytes each
count   EQU VARS + $F0          ; the frames left
NBUGS   EQU 4
X       EQU 0                       ; a record: x and y, its top left pixel
Y       EQU 1
PAT     EQU 2                       ; its first pattern
DX      EQU 3                       ; its step, each frame
DY      EQU 4
HERE    EQU 5                       ; the offset of its top left name now
WAS     EQU 7                       ; and when last sent
; Four bugs: on the bricks, a coin, the grass and the sky, each in the
; colours of the tiles under it.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $0000        ; the tiles' shapes
        ld hl, shapes
        ld c, VDP_DATA
        ld b, 112
        otir
        VRAM_WRITE $2000        ; and their colours
        ld hl, colours
        ld b, 112
        otir
        ld hl, map              ; chapter 24's screen: its names, a copy
        ld de, names
        ld bc, 768
        ldir
        ld hl, map              ; and the names on the screen, to begin with
        ld de, shown
        ld bc, 768
        ldir
        VRAM_WRITE $1800
        ld hl, names
        ld c, VDP_DATA          ; LDIR left C at 0
        ld b, 0                 ; 256
        otir
        otir
        otir
        ld hl, recs             ; the bugs' records
        ld de, bugs
        ld bc, 64
        ldir
        ld hl, copy0            ; the bug as drawn: copy 0
        ld de, copies
        ld bc, 32
        ldir
p0:     call preshift           ; and copies 1 to 7
p1:     call step               ; every bug built where it starts
        call send               ; the bugs to the VDP, the display off
        VDP_REG 1, $C0          ; the display on
done:   jr done

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret

; preshift: copies 1 to 7 of the bug, each the one before a pixel to the
; right. A copy is 32 bytes: the left column's eight rows, mask and shape,
; then the right column's, 16 bytes on; bit 4 of the address says which.
preshift: ld hl, copies         ; from copy 0
        ld de, copies + 32      ; to copy 1
        ld b, 7 * 8             ; seven copies of eight rows
.row:   scf                     ; the mask: 1 comes in at the left
        ld a, (hl)
        rra                     ; the left byte, a pixel right
        ld (de), a
        set 4, l
        set 4, e
        ld a, (hl)
        rra                     ; the right byte takes what left the left one
        ld (de), a
        res 4, l
        res 4, e
        inc l
        inc e
        or a                    ; the shape: 0 comes in at the left
        ld a, (hl)
        rra
        ld (de), a
        set 4, l
        set 4, e
        ld a, (hl)
        rra
        ld (de), a
        res 4, l
        res 4, e
        inc l
        inc e
        ld a, l
        and 15
        jr nz, .same            ; a row of the copy done; the copy done?
        ld a, l
        add a, 16
        ld l, a                 ; the next copy, past the right column
        ld a, e
        add a, 16
        ld e, a
.same:  djnz .row
        ret

; build: the bug of the record at IX into its four patterns in the RAM: the
; tiles under it, then the bug from copy x AND 7, through its mask
build:  call cells
        call buffer
        ld a, (ix + Y)
        and 7
        or l
        ld l, a                 ; HL: the left column's row for its top
        ld a, (ix + X)
        and 7
        rrca
        rrca
        rrca                    ; 32 x (x AND 7)
        ld e, a
        ld d, high copies       ; DE: its copy
        ld b, 8
        call column             ; the left column
        set 4, l                ; and the right, 16 bytes on
        res 3, l
        ld b, 8

; column: eight rows of a column of the bug's patterns: the tiles AND the
; mask, OR the bug
column: ld a, (de)              ;  8  the mask
        and (hl)                ;  8  what of the tiles stays
        inc e                   ;  5
        ex de, hl               ;  5
        or (hl)                 ;  8  and the bug
        ex de, hl               ;  5
        inc e                   ;  5
        ld (hl), a              ;  8
        inc l                   ;  5
        djnz column             ; 14, or 9
        ret

; cells: the four tiles under the bug of the record at IX into its four
; patterns in the RAM, shapes and colours; its place kept at HERE
cells:  call where
        ld (ix + HERE), l
        ld (ix + HERE + 1), h
        ld bc, names
        add hl, bc              ; the name under its top left
        push hl
        call buffer
        ex de, hl               ; DE: its first pattern in the RAM
        pop hl
        push hl
        ld a, (hl)
        call cell               ; top left
        pop hl
        push hl
        ld bc, 32
        add hl, bc
        ld a, (hl)
        call cell               ; bottom left
        pop hl
        inc hl
        push hl
        ld a, (hl)
        call cell               ; top right
        pop hl
        ld bc, 32
        add hl, bc
        ld a, (hl)
        jr cell                 ; bottom right

; cell: the 8 shape bytes of name A to DE, and its 8 colour bytes to
; DE + $400; DE comes back 8 on
cell:   push de
        call tile               ; HL: the shape bytes
        DUP 8
        ldi
        EDUP
        ld bc, $400 - 8         ; the colours are $400 on, in both places
        add hl, bc
        ex de, hl
        add hl, bc
        ex de, hl
        DUP 8
        ldi
        EDUP
        pop de
        ld a, e
        add a, 8
        ld e, a                 ; no bug's patterns cross a page
        ret

; tile: HL = the shape bytes of name A: a tile's, in the cartridge, below
; 128; a bug's pattern, in the RAM, from 128
tile:   ld l, a
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl              ; 8 x A
        cp 128
        jr nc, .bug
        ld bc, shapes
        add hl, bc
        ret
.bug:   ld bc, pats - 128 * 8
        add hl, bc
        ret

; where: HL = the offset of the name under the bug's top left, 0 to 767:
; 32 x (y / 8) + x / 8
where:  ld a, (ix + Y)
        and $F8
        ld l, a
        ld h, 0
        add hl, hl
        add hl, hl              ; 32 x (y / 8)
        ld a, (ix + X)
        rrca
        rrca
        rrca
        and 31                  ; x / 8
        or l
        ld l, a
        ret

; buffer: HL = the RAM's copy of the bug's first pattern
buffer: ld l, (ix + PAT)
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        ld bc, pats - 128 * 8
        add hl, bc
        ret

; step: every bug a step on and built again. First the names the bugs left
; in shown go back to the tiles', for all of them; then each bug moves, is
; built and puts its four names in shown
step:   ld ix, bugs
        ld a, NBUGS
.clear: push af
        call unmark
        ld bc, 16
        add ix, bc
        pop af
        dec a
        jr nz, .clear
        ld ix, bugs
        ld a, NBUGS
.move:  push af
        ld a, (ix + X)
        add a, (ix + DX)
        ld (ix + X), a
        ld a, (ix + Y)
        add a, (ix + DY)
        ld (ix + Y), a
        call build
        call mark
        ld bc, 16
        add ix, bc
        pop af
        dec a
        jr nz, .move
        ret

; unmark: the tiles' four names back in shown, where the bug is
unmark: ld l, (ix + HERE)
        ld h, (ix + HERE + 1)
        ld bc, names
        add hl, bc
        ld de, shown - names
        ex de, hl
        add hl, de
        ex de, hl               ; DE: the same name in shown
        ldi
        ldi
        ld bc, 30
        add hl, bc
        ex de, hl
        add hl, bc
        ex de, hl
        ldi
        ldi
        ret

; mark: the bug's four names in shown, where it is
mark:   ld l, (ix + HERE)
        ld h, (ix + HERE + 1)
        ld bc, shown
        add hl, bc
        ld a, (ix + PAT)
        ld (hl), a              ; top left: its first pattern
        inc hl
        add a, 2
        ld (hl), a              ; top right: the third
        ld bc, 31
        add hl, bc
        dec a
        ld (hl), a              ; bottom left: the second
        inc hl
        add a, 2
        ld (hl), a              ; bottom right: the fourth
        ret

; send: after the paper, the tiles' names back where every bug was; then
; each bug's four patterns, their colours, and its names where it is
send:   ld ix, bugs
        ld a, NBUGS
.old:   push af
        ld l, (ix + WAS)
        ld h, (ix + WAS + 1)
        ld de, names
        call two                ; the top two
        ld bc, 32
        add hl, bc
        call two                ; and the two below
        ld bc, 16
        add ix, bc
        pop af
        dec a
        jr nz, .old
        ld ix, bugs
        ld a, NBUGS
.new:   push af
        call look
        call place
        ld bc, 16
        add ix, bc
        pop af
        dec a
        jr nz, .new
        ret

; two: the names (DE + HL) and (DE + HL + 1) to the VDP, at $1800 + HL
two:    ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $58                  ; + $1800, and the bit that says write
        out (VDP_CTRL), a
        push hl
        add hl, de
        ld a, (hl)
        out (VDP_DATA), a
        inc hl
        ld a, (hl)
        out (VDP_DATA), a
        pop hl
        ret

; look: the bug's four patterns and their colours, from the RAM to the VDP
look:   ld l, (ix + PAT)
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl              ; 8 x its first pattern: its VRAM address
        ld e, l
        ld d, h
        ld a, e
        out (VDP_CTRL), a
        ld a, d
        or $40
        out (VDP_CTRL), a
        ld bc, pats - 128 * 8
        add hl, bc              ; and the RAM's
        ld bc, 32 << 8 | VDP_DATA
        otir                    ; the four patterns
        ld a, e
        out (VDP_CTRL), a
        ld a, d
        or $60                  ; $2000 on: the colours
        out (VDP_CTRL), a
        ld bc, $400 - 32
        add hl, bc
        ld bc, 32 << 8 | VDP_DATA
        otir                    ; their colours
        ret

; place: the bug's four names to the VDP where it is, and that place kept
; as where it was, for the next send
place:  ld l, (ix + HERE)
        ld h, (ix + HERE + 1)
        ld (ix + WAS), l
        ld (ix + WAS + 1), h
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $58
        out (VDP_CTRL), a
        ld a, (ix + PAT)
        out (VDP_DATA), a       ; top left
        add a, 2
        out (VDP_DATA), a       ; top right
        ld bc, 32
        add hl, bc
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $58
        out (VDP_CTRL), a
        ld a, (ix + PAT)
        inc a
        out (VDP_DATA), a       ; bottom left
        add a, 2
        out (VDP_DATA), a       ; bottom right
        ret
shapes:                         ; the tiles' shapes, name 0 on
        db $00, $00, $00, $00, $00, $00, $00, $00
        db $FF, $80, $80, $80, $FF, $08, $08, $08
        db $00, $22, $77, $FF, $00, $44, $00, $11
        db $00, $44, $00, $11, $00, $44, $00, $11
        db $20, $3F, $20, $20, $20, $3F, $20, $20
        db $04, $FC, $04, $04, $04, $FC, $04, $04
        db $00, $00, $03, $0F, $1F, $1F, $3F, $3F
        db $00, $00, $C0, $F0, $F8, $F8, $FC, $FC
        db $3F, $3F, $1F, $1F, $0F, $03, $00, $00
        db $FC, $FC, $F8, $F8, $F0, $C0, $00, $00
        db $07, $0F, $0D, $0F, $07, $03, $1F, $3F
        db $E0, $F0, $B0, $F0, $E0, $C0, $F8, $FC
        db $67, $67, $07, $06, $06, $06, $0E, $1E
        db $E6, $E6, $E0, $60, $60, $60, $70, $78
        ds shapes + $400 - $, 0 ; their colours, $400 on
colours:
        db $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F
        db $14, $14, $14, $14, $14, $14, $14, $14
        db $3F, $3F, $3F, $3F, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13
        db $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F
        db $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F
        db $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F
        db $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F
        db $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F
        db $4F, $4F, $4F, $4F, $4F, $4F, $4F, $4F
        db $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F
        db $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F
        db $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F
        db $1F, $1F, $1F, $1F, $1F, $1F, $1F, $1F
map:                            ; chapter 24's screen
        db $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01
        db $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01
        db $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01
        db $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01
        db $01, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $01
        db $01, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $01
        db $01, $01, $00, $00, $00, $00, $06, $07, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $06, $07, $00, $00, $00, $00, $01, $01
        db $01, $01, $00, $00, $00, $00, $08, $09, $00, $00, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $08, $09, $00, $00, $00, $00, $01, $01
        db $01, $01, $00, $00, $02, $02, $02, $02, $02, $02, $02, $02, $04, $05, $00, $00
        db $00, $00, $00, $00, $02, $02, $02, $02, $02, $02, $02, $02, $00, $00, $01, $01
        db $01, $01, $00, $00, $03, $03, $03, $03, $03, $03, $03, $03, $04, $05, $00, $00
        db $00, $00, $00, $00, $03, $03, $03, $03, $03, $03, $03, $03, $00, $00, $01, $01
        db $01, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $04, $05, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $01
        db $01, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $04, $05, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $01
        db $01, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $04, $05, $00, $00
        db $00, $00, $06, $07, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $01
        db $01, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $04, $05, $00, $00
        db $00, $00, $08, $09, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $01
        db $01, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $04, $05, $00, $00
        db $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $00, $00, $00, $00, $01, $01
        db $01, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $04, $05, $00, $00
        db $03, $03, $03, $03, $03, $03, $03, $03, $03, $03, $00, $00, $00, $00, $01, $01
        db $01, $01, $00, $00, $00, $00, $06, $07, $00, $00, $00, $00, $04, $05, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $01
        db $01, $01, $00, $00, $00, $00, $08, $09, $00, $00, $00, $00, $04, $05, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $01
        db $01, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $04, $05, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $06, $07, $00, $00, $01, $01
        db $01, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $04, $05, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $08, $09, $00, $00, $01, $01
        db $01, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $04, $05, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $01
        db $01, $01, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $04, $05, $00, $00
        db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $01, $01
        db $01, $01, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02
        db $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $01, $01
        db $01, $01, $03, $03, $03, $03, $03, $03, $03, $03, $03, $03, $03, $03, $03, $03
        db $03, $03, $03, $03, $03, $03, $03, $03, $03, $03, $03, $03, $03, $03, $01, $01
        db $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01
        db $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01
        db $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01
        db $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01, $01
copy0:                          ; the bug: left column, mask and shape a row
        db $81, $24, $81, $18, $00, $3C, $00, $5A
        db $00, $3C, $00, $5A, $00, $3C, $00, $42
        db $FF, $00, $FF, $00, $FF, $00, $FF, $00   ; the right column: nothing
        db $FF, $00, $FF, $00, $FF, $00, $FF, $00   ; the right column: nothing
rows:                           ; the bug's rows, mask and shape, for sbuild
        db $81, $24, $81, $18, $00, $3C, $00, $5A
        db $00, $3C, $00, $5A, $00, $3C, $00, $42
recs:                           ; x, y, the first pattern, dx, dy
        db $64, $04, $80, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $34, $25, $84, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $44, $32, $88, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        db $78, $24, $8C, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
